const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pointSE = ee.Geometry.Point([121.96499287870442, 24.83594812988359]);
  const pointNW = ee.Geometry.Point([121.93452298429524, 24.84607374884142]);
  const targetDate = '2021-09-29';

  // Create small buffer around points for sampling
  const regionSE = pointSE.buffer(50);
  const regionNW = pointNW.buffer(50);

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate('2021-09-29', '2021-09-30')
    .filterBounds(pointSE.buffer(5000));

  let colSize = collection.size().getInfo();
  console.log(`Initial Sentinel-2 images: ${colSize}`);

  if (colSize === 0) {
    // Try wider date range
    collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate('2021-09-25', '2021-10-05')
      .filterBounds(pointSE.buffer(5000));
    colSize = collection.size().getInfo();
    console.log(`Expanded date range images: ${colSize}`);

    if (colSize === 0) {
      console.log('No images found for the location and date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Processing
  const image = collection.map(maskClouds).median();

  // Use blue band (B2) and green band (B3) to assess water color
  // Lighter blue water = higher reflectance in visible bands
  const blueGreen = image.select(['B2', 'B3', 'B4']);

  // Check pixel counts for both locations
  const countSE = blueGreen.select('B2').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: regionSE,
    scale: 10,
    maxPixels: 1e9
  }).get('B2').getInfo();

  const countNW = blueGreen.select('B2').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: regionNW,
    scale: 10,
    maxPixels: 1e9
  }).get('B2').getInfo();

  console.log(`SE valid pixels: ${countSE}, NW valid pixels: ${countNW}`);

  if (countSE === 0 || countNW === 0) {
    console.log('No valid pixels after masking for one or both locations.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - compute average brightness (blue+green bands)
  const statsSE = blueGreen.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: regionSE,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const statsNW = blueGreen.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: regionNW,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const blueSE = statsSE.B2;
  const blueNW = statsNW.B2;
  const greenSE = statsSE.B3;
  const greenNW = statsNW.B3;

  console.log(`SE - Blue: ${blueSE}, Green: ${greenSE}`);
  console.log(`NW - Blue: ${blueNW}, Green: ${greenNW}`);

  // 5. Validation & Final Answer
  if (blueSE == null || blueNW == null || greenSE == null || greenNW == null) {
    console.log('Calculation returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(blueSE) || isNaN(blueNW)) {
    console.log('Calculation returned NaN.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate overall brightness (lighter blue = higher reflectance)
  const brightnessSE = (blueSE + greenSE) / 2;
  const brightnessNW = (blueNW + greenNW) / 2;

  console.log(`SE brightness: ${brightnessSE.toFixed(2)}, NW brightness: ${brightnessNW.toFixed(2)}`);

  if (brightnessSE > brightnessNW) {
    console.log('Southeast coast exhibits lighter blue coloration.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Southeast coast does NOT exhibit lighter blue coloration.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
